import{_t as e,it as t,n,rt as r}from"./chunks/framework.DaD4z1Q-.js";var i=JSON.parse(`{"title":"Benchmarks","description":"","frontmatter":{},"headers":[],"relativePath":"benchmarks.md","filePath":"benchmarks.md"}`),a={name:`benchmarks.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="benchmarks" tabindex="-1">Benchmarks <a class="header-anchor" href="#benchmarks" aria-label="Permalink to “Benchmarks”">​</a></h1><p>These are timings of <code>prefix</code> for Strauss PHP and Strauss-RS on four projects of different sizes. They were taken on one machine, so treat them as a guide to the size of the difference. Your results will vary with your hardware, your project and your disk.</p><h2 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to “Results”">​</a></h2><p>Each time is the median of several runs: seven for the small and medium projects, three for the large and extra large ones.</p><table tabindex="0"><thead><tr><th>Project</th><th style="text-align:right;">Packages</th><th style="text-align:right;">PHP files</th><th style="text-align:right;">Strauss PHP 0.31.1</th><th style="text-align:right;">Strauss-RS</th><th style="text-align:right;">Strauss-RS, 1 thread</th></tr></thead><tbody><tr><td>Small (<code>monolog</code>)</td><td style="text-align:right;">2</td><td style="text-align:right;">142</td><td style="text-align:right;">0.82 s</td><td style="text-align:right;">0.012 s</td><td style="text-align:right;">0.025 s</td></tr><tr><td>Medium (<code>guzzle</code>, <code>flysystem</code>, <code>finder</code>)</td><td style="text-align:right;">12</td><td style="text-align:right;">266</td><td style="text-align:right;">1.52 s</td><td style="text-align:right;">0.018 s</td><td style="text-align:right;">0.054 s</td></tr><tr><td>Large (<code>laravel/framework</code>)</td><td style="text-align:right;">73</td><td style="text-align:right;">5,369</td><td style="text-align:right;">19.3 s</td><td style="text-align:right;">0.18 s</td><td style="text-align:right;">0.73 s</td></tr><tr><td>Extra large (<code>aws/aws-sdk-php</code>)</td><td style="text-align:right;">15</td><td style="text-align:right;">3,769</td><td style="text-align:right;">47.0 s</td><td style="text-align:right;">0.36 s</td><td style="text-align:right;">1.40 s</td></tr></tbody></table><p>Dividing the Strauss PHP time by the Strauss-RS time gives these ratios. The times have two significant figures, so the ratios are rounded the same way:</p><table tabindex="0"><thead><tr><th>Project</th><th style="text-align:right;">Against Strauss-RS</th><th style="text-align:right;">Against Strauss-RS on 1 thread</th></tr></thead><tbody><tr><td>Small</td><td style="text-align:right;">about 68 times</td><td style="text-align:right;">about 33 times</td></tr><tr><td>Medium</td><td style="text-align:right;">about 84 times</td><td style="text-align:right;">about 28 times</td></tr><tr><td>Large</td><td style="text-align:right;">about 110 times</td><td style="text-align:right;">about 26 times</td></tr><tr><td>Extra large</td><td style="text-align:right;">about 130 times</td><td style="text-align:right;">about 34 times</td></tr></tbody></table><p>The single-thread column shows how much of the difference comes from the program and how much from using several CPUs. Strauss-RS uses one worker per CPU by default, and Strauss PHP runs on one.</p><h2 id="how-they-were-run" tabindex="-1">How they were run <a class="header-anchor" href="#how-they-were-run" aria-label="Permalink to “How they were run”">​</a></h2><ul><li>PHP 8.4.26, with OPCache off and no memory limit.</li><li>A system with 12 threads. The CPU model, memory, operating system and disk are not recorded.</li><li>Strauss PHP 0.31.1 and Strauss-RS were run on the same four projects.</li></ul><h2 id="what-to-keep-in-mind" tabindex="-1">What to keep in mind <a class="header-anchor" href="#what-to-keep-in-mind" aria-label="Permalink to “What to keep in mind”">​</a></h2><ul><li>The times are short for the small and medium projects, so a few milliseconds of start-up time makes a large difference to the ratio. The ratios for those projects are the least reliable.</li><li>The large and extra large projects had only three runs each.</li><li>These measure the <code>prefix</code> step. A Composer install and your own build steps take the same time with either tool.</li></ul>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};